@router.delete({{path}}, status_code=204)
def delete_child(parent_id: int, child_id: int, db: Annotated[Session, Depends(session_provider)]) -> Response:
    """Delete child."""
    row = _require_child(db, parent_id, child_id)
    db.delete(row)
    try:
        db.commit()
    except IntegrityError as exc:
        integrity_failure(db, exc)
    return Response(status_code=204)
